                .orElseThrow(() -> ApiException.conflict("批次未处于召回上下文，无需复检: " + batchKey));
        // 先锁根召回批次再锁本批（与召回/解除批准的锁顺序一致），按提交顺序裁决
        BatchRepository.BatchRow root = repo.findBatchForUpdate(rootKey).get();
        if (!BatchStatus.RECALLED.name().equals(root.status())) {
            throw ApiException.conflict("召回上下文已解除，请重新提交: " + rootKey);
        }
        if (!rootKey.equals(batchKey)) {
