            BatchRepository.ReleaseRow row = new BatchRepository.ReleaseRow(0L, batchKey,
                    req.releaseKey(), req.commandKey(), req.recallVersion(), req.correctiveAction(),
                    String.join(",", normalized), actor, "PENDING", null, null, now);
